import { database } from './index';
import { seedDatabase } from './seed';
import { migrate } from 'drizzle-orm/expo-sqlite/migrator';
import m0000 from './migrations/0000_marvelous_praxagora';
import migrationJournal from './migrations/meta/_journal.json';

/**
 * Initializes the database.
 *
 * Flow:
 *   1. Apply pending schema migrations generated by drizzle-kit
 *      (idempotent: drizzle tracks applied migrations in the
 *      `__drizzle_migrations` table; safe to call on every launch).
 *   2. Seed default categories (only if the table is empty).
 *
 * The migration SQL lives in src/database/migrations/. It is committed
 * to the repository so a clean install on a fresh device bootstraps
 * the full schema before seedDatabase() runs its first SELECT.
 */
export async function initializeDatabase(): Promise<void> {
  // 1. Apply schema migrations (creates all 10 tables + foreign keys).
  await migrate(database, {
    journal: migrationJournal,
    migrations: {
      m0000,
    },
  });

  // 2. Seed default categories (only if table is empty).
  // TODO: Replace 'default-user' with authenticated user ID when auth is implemented
  await seedDatabase('default-user');
}

// =============================================================================
// REGENERATING MIGRATIONS
// =============================================================================
//
// 1. Edit src/database/schema.ts
// 2. Run: npx drizzle-kit generate
// 3. A new 000N_*.sql file appears under src/database/migrations/
// 4. Mirror it as a .ts default-string export (Metro cannot bundle .sql
//    files natively) and add the entry to the `migrations` map above.
// 5. Update the `migrations` Record to include the new key (m0001, ...).
//
// The migration runner is idempotent: it keeps a `__drizzle_migrations`
// table and skips already-applied entries.
